//! Default-value extraction for OpenAPI schema generation.
//!
//! Handles the three sources of struct field defaults:
//! 1. Pre-extracted `SCHEMA_STORAGE` defaults (populated by `#[derive(Schema)]`)
//! 2. `#[schema(default = "...")]` attributes (generated by `schema_type!`)
//! 3. `#[serde(default)]` / `#[serde(default = "fn_name")]` attributes
//!    (the function variant needs a parsed file AST)

use std::{
    cell::RefCell,
    collections::{BTreeMap, BTreeSet, HashMap},
    sync::Arc,
};

use crate::{
    parser::{
        extract_default, rename_field,
        schema::{
            SerdeSide, derives_serialize, extract_field_rename_owned, extract_rename_all_for,
            extract_serde_rename_all,
        },
        strip_raw_prefix_owned,
    },
    schema_macro::type_utils::get_type_default as utils_get_type_default,
};

/// Set the default value on a property schema, if not already set.
///
/// Looks up `field_name` in the properties map. An inline schema without a
/// default gets `value`; a pure `$ref` becomes `{"$ref": .., "default": ..}`
/// (OpenAPI 3.1 allows siblings of `$ref`), so an explicit
/// `#[schema(default = "active")]` on an enum-typed field is documented.
pub(super) fn set_property_default(
    properties: &mut BTreeMap<String, vespera_core::schema::SchemaRef>,
    field_name: &str,
    value: serde_json::Value,
) {
    use vespera_core::schema::{Schema, SchemaRef, SchemaType};

    if let Some(property) = properties.get_mut(field_name)
        && let SchemaRef::Ref(reference) = property
    {
        let ref_path = std::mem::take(&mut reference.ref_path);
        *property = SchemaRef::Inline(Box::new(Schema {
            ref_path: Some(ref_path),
            default: Some(value),
            ..Schema::default()
        }));
        return;
    }
    if let Some(SchemaRef::Inline(prop_schema)) = properties.get_mut(field_name)
        && prop_schema.default.is_none()
    {
        // A default on a string-typed property must itself be a string — e.g. a
        // `Decimal` field (string wire type) carrying a numeric DB default value.
        let value = if prop_schema.schema_type == Some(SchemaType::String) {
            match value {
                serde_json::Value::Number(n) => serde_json::Value::String(n.to_string()),
                serde_json::Value::Bool(b) => serde_json::Value::String(b.to_string()),
                other => other,
            }
        } else {
            value
        };
        prop_schema.default = Some(value);
    }
}

/// Process default functions for struct fields
/// This function extracts default values from:
/// 1. `#[schema(default = "value")]` attributes (generated by `schema_type!` from `sea_orm(default_value)`)
/// 2. `#[serde(default = "function_name")]` by finding the function in the file AST
/// 3. `#[serde(default)]` by using type-specific defaults
#[cfg(test)]
pub(super) fn process_default_functions(
    struct_item: &syn::ItemStruct,
    file_ast: Option<&syn::File>,
    schema: &mut vespera_core::schema::Schema,
    stored_defaults: &BTreeMap<String, serde_json::Value>,
) {
    process_default_functions_for(
        struct_item,
        file_ast,
        schema,
        stored_defaults,
        SerdeSide::Serialize,
        &[],
    );
}

/// Component name → the `#[serde(default = "fn")]` values `#[derive(Schema)]`
/// resolved for it ([`crate::metadata::StructMetadata::field_defaults`]),
/// for every component that has any.
pub type StoredDefaults = Arc<HashMap<String, BTreeMap<String, serde_json::Value>>>;

thread_local! {
    static STORED_DEFAULTS: RefCell<StoredDefaults> = RefCell::new(Arc::default());
}

/// The stored defaults of every `metadata` struct that has any.
pub fn stored_defaults_of(metadata: &crate::metadata::CollectedMetadata) -> StoredDefaults {
    Arc::new(
        metadata
            .structs
            .iter()
            .filter(|meta| !meta.field_defaults.is_empty())
            .map(|meta| (meta.name.clone(), meta.field_defaults.clone()))
            .collect(),
    )
}

/// The installed stored-default map (for handing to worker threads).
pub fn snapshot_stored_defaults() -> StoredDefaults {
    STORED_DEFAULTS.with(|slot| Arc::clone(&slot.borrow()))
}

/// Install `defaults` on this thread; returns the previous map.
pub fn install_stored_defaults(defaults: StoredDefaults) -> StoredDefaults {
    STORED_DEFAULTS.with(|slot| slot.replace(defaults))
}

/// The field defaults of a generic instantiation (`Tree<i32>`, its
/// substituted definition `item`) of the component `generic` in the view
/// being built: the same `#[schema(default)]` / `#[serde(default)]` defaults
/// the generic component gets, `#[serde(default = "fn")]` values included —
/// read from the generic component's stored defaults (installed for the
/// generation, see [`install_stored_defaults`]).
pub fn instance_defaults(
    generic: &str,
    item: &syn::ItemStruct,
    schema: &mut vespera_core::schema::Schema,
) {
    let stored = snapshot_stored_defaults();
    let empty = BTreeMap::new();
    // The generic's source module is not at hand here, so its field types
    // resolve at the call site (as before).
    let module = crate::schema_macro::call_site_module().unwrap_or_default();
    process_default_functions_for(
        item,
        None,
        schema,
        stored.get(generic).unwrap_or(&empty),
        crate::parser::schema::request_view::current_side(),
        &module,
    );
}

/// [`process_default_functions`] for the `side` view of the struct: the
/// request (`{Name}Input`) view keys its properties by the deserialize name.
/// `source_module` is the absolute module (`crate::..`) the struct is
/// declared in, which its field types resolve in.
pub fn process_default_functions_for(
    struct_item: &syn::ItemStruct,
    file_ast: Option<&syn::File>,
    schema: &mut vespera_core::schema::Schema,
    stored_defaults: &BTreeMap<String, serde_json::Value>,
    side: SerdeSide,
    source_module: &[String],
) {
    use syn::Fields;

    // Cheap O(field_attrs) precheck: when `stored_defaults` is empty AND no
    // field carries a `serde` or `schema` attribute, NONE of the three
    // priority paths below can fire and the `required` demotion stays empty
    // — so the rest of this function is provably a no-op. The early-return
    // is observably equivalent to the full walk: the emitted `Schema` stays
    // byte-identical (the `insta` snapshots in `crates/vespera_macro/src/
    // snapshots/` are the runtime-neutrality lock).
    //
    // Bench fixture (`benches/macro-compile-bench`) has 14 component schemas
    // and NONE carry `#[serde(default)]` / `#[schema(default)]`, so the
    // pre-extracted `field_defaults` is empty for all of them — every full
    // `macro_expand_crate` previously paid ~14 struct-level walks + ~70
    // per-field iterations of `parse_nested_meta` for pure no-op work.
    if stored_defaults.is_empty() && !any_field_carries_default_relevant_attr(struct_item) {
        return;
    }

    let owner_serializes = derives_serialize(&struct_item.attrs);
    // Extract rename_all from struct level. The serialize view of an owner
    // that derives `Serialize` names fields as serde writes them: the
    // `try_from_multipart` fallback names form fields only.
    let struct_rename_all = if owner_serializes && side == SerdeSide::Serialize {
        extract_serde_rename_all(&struct_item.attrs)
    } else {
        extract_rename_all_for(&struct_item.attrs, side)
    };

    // Locate the object schema that actually holds the fields. Flatten structs
    // are `allOf`-shaped: their own (non-flattened) fields live in the first
    // inline `allOf` member, not a top-level `properties` map — defaults (and
    // the `required` demotion below) must apply there too.
    let Some(target) = field_bearing_schema_mut(schema) else {
        return;
    };

    // Every `#[serde(default)]` field is wire-optional: serde accepts payloads
    // with that key omitted. Requiredness therefore depends on wire presence,
    // not on whether we could statically extract the default value.
    let mut serde_default_fields: BTreeSet<String> = BTreeSet::new();
    let function_index = file_ast.map(function_index_by_name);

    // Process each field in the struct
    if let Some(properties) = target.properties.as_mut()
        && let Fields::Named(fields_named) = &struct_item.fields
    {
        for field in &fields_named.named {
            let rust_field_name = field.ident.as_ref().map_or_else(
                || "unknown".to_string(),
                |i| strip_raw_prefix_owned(i.to_string()),
            );
            let field_name = extract_field_rename_owned(&field.attrs, side, owner_serializes)
                .unwrap_or_else(|| rename_field(&rust_field_name, struct_rename_all.as_deref()));

            // Recorded before the value priorities below, which may `continue`:
            // the demotion depends on the attribute, not on how the value was found.
            if extract_default(&field.attrs).is_some() {
                serde_default_fields.insert(field_name.clone());
            }

            // Priority 0: Pre-extracted defaults from SCHEMA_STORAGE (populated by #[derive(Schema)])
            if let Some(value) = stored_defaults.get(&rust_field_name) {
                set_property_default(properties, &field_name, value.clone());
                continue;
            }

            // Priority 1: #[schema(default = "value")] from schema_type! macro.
            // The attribute value is a string literal; for a string-typed field
            // use it VERBATIM so lexical form is preserved (e.g. a leading-zero
            // id `"00123"` must NOT normalise to `"123"`), otherwise infer the
            // JSON type from the string.
            if let Some(default_str) = extract_schema_default_attr(&field.attrs) {
                let value = schema_default_value(properties.get(&field_name), default_str);
                set_property_default(properties, &field_name, value);
                continue;
            }

            // Priority 2: #[serde(default)] / #[serde(default = "fn")]
            let default_info = match extract_default(&field.attrs) {
                Some(Some(func_name)) => func_name,
                Some(None) => {
                    // Simple default (no function): use the type-specific default
                    // when known. Unresolvable defaults are rejected earlier by
                    // `#[derive(Schema)]`, so this fallback only preserves unit
                    // test behaviour when called directly.
                    if let Some(default_value) = utils_get_type_default(&field.ty, source_module) {
                        set_property_default(properties, &field_name, default_value);
                    }
                    continue;
                }
                None => continue, // No default attribute
            };

            // Priority 2 (function form) is the only step that needs the AST.
            // Unresolvable values are rejected earlier by `#[derive(Schema)]`;
            // this path simply omits the `default` when invoked directly in
            // tests without that derive-time validation.
            let resolved = function_index
                .as_ref()
                .and_then(|index| find_function_in_index(index, &default_info))
                .and_then(extract_default_value_from_function);
            if let Some(default_value) = resolved {
                set_property_default(properties, &field_name, default_value);
            }
        }
    }

    // Demote every serde-default field from `required` in the REQUEST view:
    // serde fills an omitted key in on input, however the default value was
    // obtained. The response view keeps it required: serde writes a
    // `#[serde(default)]` field on output unless `skip_serializing_if` omits
    // it (the response `required` is computed in `parser/schema/struct_schema.rs`).
    if side == SerdeSide::Deserialize && !serde_default_fields.is_empty() {
        if let Some(required) = target.required.as_mut() {
            required.retain(|name| !serde_default_fields.contains(name));
        }
        if target.required.as_ref().is_some_and(Vec::is_empty) {
            target.required = None;
        }
    }
}

/// Returns `true` if any named field on `struct_item` carries a `#[serde(...)]`
/// or `#[schema(...)]` attribute — the only attributes that can possibly
/// trigger any of `process_default_functions`'s three priority paths.
///
/// Only inspects the attribute path (an `Ident` comparison) — never calls
/// `parse_nested_meta`, so this stays O(sum of field attr counts) byte
/// comparisons. Tuple/unit structs return `false` immediately (matching the
/// `Fields::Named` branch in the caller).
fn any_field_carries_default_relevant_attr(struct_item: &syn::ItemStruct) -> bool {
    let syn::Fields::Named(fields) = &struct_item.fields else {
        return false;
    };
    fields.named.iter().any(|field| {
        field
            .attrs
            .iter()
            .any(|attr| attr.path().is_ident("serde") || attr.path().is_ident("schema"))
    })
}

/// Return the object schema that actually carries the struct's fields: the
/// schema itself, or — for flatten/`allOf`-shaped structs — the first inline
/// `allOf` member (where the non-flattened fields live).
fn field_bearing_schema_mut(
    schema: &mut vespera_core::schema::Schema,
) -> Option<&mut vespera_core::schema::Schema> {
    if schema.properties.is_some() {
        return Some(schema);
    }
    schema
        .all_of
        .as_mut()?
        .iter_mut()
        .find_map(|member| match member {
            vespera_core::schema::SchemaRef::Inline(inline) => Some(inline.as_mut()),
            vespera_core::schema::SchemaRef::Ref(_) => None,
        })
}

/// Extract `default` value from `#[schema(default = "...")]` field attribute.
///
/// This attribute is generated by `schema_type!` when converting `sea_orm(default_value)`.
/// It carries the raw default value string for OpenAPI schema generation.
/// Other keys in the same list (`#[schema(format = "x", default = "1")]`)
/// are skipped, never ending the search early.
pub(super) fn extract_schema_default_attr(attrs: &[syn::Attribute]) -> Option<String> {
    crate::parser::schema::extract_schema_default(attrs).flatten()
}

/// The JSON value of a `#[schema(default = "...")]` literal for the property
/// (`property`) it documents.
///
/// A string-typed property keeps the literal VERBATIM so its lexical form
/// survives (a leading-zero id `"00123"` must NOT normalise to `"123"`). A
/// `$ref` or an allOf wrapper (a doc-commented field) does not record its wire
/// type here, so see [`untyped_default_value`].
fn schema_default_value(
    property: Option<&vespera_core::schema::SchemaRef>,
    literal: String,
) -> serde_json::Value {
    use vespera_core::schema::{SchemaRef, SchemaType};
    match property {
        Some(SchemaRef::Inline(schema)) if schema.schema_type == Some(SchemaType::String) => {
            serde_json::Value::String(literal)
        }
        Some(SchemaRef::Ref(_)) => untyped_default_value(literal),
        Some(SchemaRef::Inline(schema)) if schema.schema_type.is_none() => {
            untyped_default_value(literal)
        }
        _ => parse_default_string_to_json_value(&literal),
    }
}

/// The JSON value of a literal whose property's wire type is unknown.
///
/// The literal becomes a number / bool / `null` / array / object only when that
/// value serialises back to exactly the same text (`"7"` → `7`), so `"007"` on a
/// `$ref` to a string newtype stays the string `"007"` instead of the number `7`.
fn untyped_default_value(literal: String) -> serde_json::Value {
    let parsed = parse_default_string_to_json_value(&literal);
    if !matches!(parsed, serde_json::Value::String(_))
        && serde_json::to_string(&parsed).is_ok_and(|text| text == literal)
    {
        parsed
    } else {
        serde_json::Value::String(literal)
    }
}

// Parse a default value string into the appropriate `serde_json::Value`.
///
/// Tries to infer the JSON type: array / object → `null` → integer → number → bool →
/// string (fallback).
pub(super) fn parse_default_string_to_json_value(value: &str) -> serde_json::Value {
    // A JSON array / object (`"[]"`, `"{"a": 1}"`) for a non-string field.
    if let Ok(json @ (serde_json::Value::Array(_) | serde_json::Value::Object(_))) =
        serde_json::from_str::<serde_json::Value>(value)
    {
        return json;
    }
    // `null` (an `Option` field's `None`), never the string `"null"`.
    if value == "null" {
        return serde_json::Value::Null;
    }
    // An integer literal is never an `f64`: through `f64` a value past 2^53
    // (or past `u64::MAX`) rounds to a non-integer. It is an `i64` or `u64`
    // number, else the literal stays text.
    let integer_literal = value.strip_prefix('-').unwrap_or(value);
    if !integer_literal.is_empty() && integer_literal.bytes().all(|b| b.is_ascii_digit()) {
        if let Ok(n) = value.parse::<i64>() {
            return serde_json::Value::Number(n.into());
        }
        if let Ok(n) = value.parse::<u64>() {
            return serde_json::Value::Number(n.into());
        }
        return serde_json::Value::String(value.to_string());
    }
    // Try float
    if let Ok(f) = value.parse::<f64>()
        && let Some(n) = serde_json::Number::from_f64(f)
    {
        return serde_json::Value::Number(n);
    }
    // Try bool
    if let Ok(b) = value.parse::<bool>() {
        return serde_json::Value::Bool(b);
    }
    // Fallback to string
    serde_json::Value::String(value.to_string())
}

/// Find a function by name in the file AST
#[cfg(test)]
pub fn find_function_in_file<'a>(
    file_ast: &'a syn::File,
    function_name: &str,
) -> Option<&'a syn::ItemFn> {
    let index = function_index_by_name(file_ast);
    find_function_in_index(&index, function_name)
}

/// The top-level functions of `file_ast` by name. A name declared more than
/// once (`#[cfg]`-gated twins) is ambiguous: this file does not say which
/// twin the build keeps, so it maps to `None` and callers treat it as
/// unresolved. Route signatures (`paths.rs`) use the same index and rule.
pub(super) fn function_index_by_name(
    file_ast: &syn::File,
) -> HashMap<String, Option<&syn::ItemFn>> {
    let mut functions: HashMap<String, Option<&syn::ItemFn>> = HashMap::new();
    for item in &file_ast.items {
        if let syn::Item::Fn(fn_item) = item {
            functions
                .entry(fn_item.sig.ident.to_string())
                .and_modify(|slot| *slot = None)
                .or_insert(Some(fn_item));
        }
    }
    functions
}

fn find_function_in_index<'a>(
    function_index: &HashMap<String, Option<&'a syn::ItemFn>>,
    function_name: &str,
) -> Option<&'a syn::ItemFn> {
    // The index holds only this file's top-level functions. A qualified path
    // (`crate::config::d`) names another module's `d`, and matching it by its
    // last segment would document a same-named local function's value.
    if function_name.contains("::") {
        return None;
    }
    function_index.get(function_name).copied().flatten()
}

/// Extract default value from function body
/// This tries to extract literal values from common patterns like:
/// - "`value".to_string()` -> "value"
/// - 42 -> 42
/// - true -> true
/// - vec![] -> []
pub fn extract_default_value_from_function(func: &syn::ItemFn) -> Option<serde_json::Value> {
    // Only the function's LAST statement can supply the value. An earlier
    // literal statement is not the result, and a `return` / branch before it
    // (`if flag { return 1; } 3`) means the literal is not the only outcome.
    let (last, rest) = func.block.stmts.split_last()?;
    if rest.iter().any(may_exit_early) {
        return None;
    }
    let syn::Stmt::Expr(expr, _) = last else {
        return None;
    };
    // Direct expression (like "value".to_string())
    if let Some(value) = extract_value_from_expr(expr) {
        return Some(value);
    }
    // Or a return statement
    if let syn::Expr::Return(ret) = expr
        && let Some(expr) = &ret.expr
    {
        return extract_value_from_expr(expr);
    }
    None
}

/// Whether `stmt` contains anything that can leave the function body before
/// its last statement: `return`, `?`, or a branch / loop (which may hold one).
fn may_exit_early(stmt: &syn::Stmt) -> bool {
    use syn::visit::Visit;

    struct ExitFinder(bool);
    impl<'ast> Visit<'ast> for ExitFinder {
        fn visit_macro(&mut self, _: &'ast syn::Macro) {
            // A macro body is only tokens: a `return` or `?` inside it is not
            // visible to this walk, so any macro before the tail may exit.
            self.0 = true;
        }

        fn visit_expr(&mut self, expr: &'ast syn::Expr) {
            if matches!(
                expr,
                syn::Expr::Return(_)
                    | syn::Expr::Try(_)
                    | syn::Expr::If(_)
                    | syn::Expr::Match(_)
                    | syn::Expr::Loop(_)
                    | syn::Expr::While(_)
                    | syn::Expr::ForLoop(_)
            ) {
                self.0 = true;
            }
            syn::visit::visit_expr(self, expr);
        }
    }

    let mut finder = ExitFinder(false);
    finder.visit_stmt(stmt);
    finder.0
}

/// The value of `-expr` for a numeric literal `expr`.
fn negated_value(expr: &syn::Expr) -> Option<serde_json::Value> {
    // An integer literal's magnitude may exceed `i64::MAX` by one
    // (`-9223372036854775808` is `i64::MIN`): negate it unsigned.
    if let syn::Expr::Lit(syn::ExprLit {
        lit: syn::Lit::Int(int),
        ..
    }) = expr
        && !matches!(int.suffix(), "f32" | "f64")
    {
        let magnitude = int.base10_parse::<u64>().ok()?;
        return 0_i64
            .checked_sub_unsigned(magnitude)
            .map(serde_json::Value::from);
    }
    match extract_value_from_expr(expr)? {
        serde_json::Value::Number(n) => n
            .as_i64()
            .and_then(i64::checked_neg)
            .map(serde_json::Value::from)
            .or_else(|| {
                n.as_f64()
                    .and_then(|v| serde_json::Number::from_f64(-v))
                    .map(serde_json::Value::Number)
            }),
        _ => None,
    }
}

/// The value of an argument-less conversion of a literal: `to_owned` /
/// `into` keep a string, `to_string` also renders a number or bool as the
/// STRING Rust's `Display` produces (`42.to_string()` is `"42"`,
/// `1.0.to_string()` is `"1"`, `1e20.to_string()` is
/// `"100000000000000000000"`).  An `f32` literal is not rendered: its
/// `Display` reads the `f32`-rounded value, not the decimal written.
fn method_call_value(call: &syn::ExprMethodCall) -> Option<serde_json::Value> {
    use serde_json::Value;
    if !call.args.is_empty() || is_f32_literal(&call.receiver) {
        return None;
    }
    match (
        call.method.to_string().as_str(),
        extract_value_from_expr(&call.receiver)?,
    ) {
        ("to_owned" | "into" | "to_string", value @ Value::String(_)) => Some(value),
        ("to_string", Value::Number(n)) => Some(Value::String(match n.as_f64() {
            Some(v) if n.is_f64() => v.to_string(),
            _ => n.to_string(),
        })),
        ("to_string", value @ Value::Bool(_)) => Some(Value::String(value.to_string())),
        _ => None,
    }
}

/// The value of an integer literal. A float suffix (`16777217f32`,
/// `9007199254740993f64`) makes the literal the float Rust reads it as: the
/// nearest value of that precision, not the integer it spells.
fn int_literal_value(int: &syn::LitInt) -> Option<serde_json::Value> {
    match int.suffix() {
        "f32" => int
            .base10_parse::<f32>()
            .ok()
            .and_then(|v| serde_json::Number::from_f64(f64::from(v)))
            .map(serde_json::Value::Number),
        "f64" => int
            .base10_parse::<f64>()
            .ok()
            .and_then(serde_json::Number::from_f64)
            .map(serde_json::Value::Number),
        // Past `i64::MAX` a positive literal is a `u64`, as in the string path.
        _ => int
            .base10_parse::<i64>()
            .map(serde_json::Value::from)
            .or_else(|_| int.base10_parse::<u64>().map(serde_json::Value::from))
            .ok(),
    }
}

/// `1.5f32` (possibly parenthesized or negated).
fn is_f32_literal(expr: &syn::Expr) -> bool {
    match expr {
        syn::Expr::Lit(syn::ExprLit {
            lit: syn::Lit::Float(float),
            ..
        }) => float.suffix() == "f32",
        // `16777217f32`: integer digits with a float suffix lex as `LitInt`.
        syn::Expr::Lit(syn::ExprLit {
            lit: syn::Lit::Int(int),
            ..
        }) => int.suffix() == "f32",
        syn::Expr::Paren(inner) => is_f32_literal(&inner.expr),
        syn::Expr::Unary(unary) => is_f32_literal(&unary.expr),
        _ => false,
    }
}

/// Extract value from expression
pub(super) fn extract_value_from_expr(expr: &syn::Expr) -> Option<serde_json::Value> {
    use syn::{Expr, ExprLit, ExprMacro, Lit};

    match expr {
        // Literal values
        Expr::Lit(ExprLit { lit, .. }) => match lit {
            Lit::Str(s) => Some(serde_json::Value::String(s.value())),
            Lit::Int(i) => int_literal_value(i),
            Lit::Float(f) => f
                .base10_parse::<f64>()
                .ok()
                .and_then(serde_json::Number::from_f64)
                .map(serde_json::Value::Number),
            Lit::Bool(b) => Some(serde_json::Value::Bool(b.value)),
            _ => None,
        },
        // `-1` / `-0.5`: a negated numeric literal.
        Expr::Unary(syn::ExprUnary {
            op: syn::UnOp::Neg(_),
            expr,
            ..
        }) => negated_value(expr),
        // `(5)` / `-(-1)`: parentheses do not change the value.
        Expr::Paren(paren) => extract_value_from_expr(&paren.expr),
        // `"value".to_string()` / `.to_owned()` / `.into()`, `42.to_string()`
        Expr::MethodCall(method_call) => method_call_value(method_call),
        // Associated function calls like String::from("value")
        Expr::Call(call) => {
            let Expr::Path(path) = call.func.as_ref() else {
                return None;
            };
            let mut segments = path.path.segments.iter().rev();
            let last = segments.next()?;
            let prev = segments.next()?;
            // `String::new()` / `Vec::new()`: the empty value.
            if last.ident == "new" && call.args.is_empty() {
                return match prev.ident.to_string().as_str() {
                    "String" => Some(serde_json::Value::String(String::new())),
                    "Vec" => Some(serde_json::Value::Array(Vec::new())),
                    _ => None,
                };
            }
            if last.ident == "from"
                && prev.ident == "String"
                && call.args.len() == 1
                && let Some(first_arg) = call.args.first()
            {
                return extract_value_from_expr(first_arg).and_then(|value| match value {
                    serde_json::Value::String(_) => Some(value),
                    _ => None,
                });
            }
            None
        }
        // Macro calls like vec![...]
        Expr::Macro(ExprMacro { mac, .. }) => {
            if mac.path.is_ident("vec") {
                // `vec![]` → empty array.  `vec![a, b, ...]` → the array of its
                // element values, but ONLY when every element resolves to a
                // literal; otherwise the default is unrepresentable and we
                // return `None` (the field is then demoted from `required`)
                // rather than emitting a WRONG empty `[]` for a non-empty
                // `vec!` (the prior behaviour silently dropped the elements).
                if mac.tokens.is_empty() {
                    return Some(serde_json::Value::Array(Vec::new()));
                }
                return mac
                    .parse_body_with(
                        syn::punctuated::Punctuated::<Expr, syn::Token![,]>::parse_terminated,
                    )
                    .ok()
                    .and_then(|elems| {
                        elems
                            .iter()
                            .map(extract_value_from_expr)
                            .collect::<Option<Vec<_>>>()
                    })
                    .map(serde_json::Value::Array);
            }
            None
        }
        _ => None,
    }
}

